package me.crsib.freecartracker.data.entity

/**
 * Common identity/clock for the three ledger entry types (fuel, charge, expense). [syncId] is a
 * stable cross-device id (UUID) so entries can be merged by identity instead of replaced wholesale;
 * [updatedAtMillis] is a per-row last-write clock used to resolve edit conflicts during sync.
 */
interface LedgerRow {
    /** Local Room row id (autogenerated); not stable across devices. */
    val id: Long
    val syncId: String
    val updatedAtMillis: Long
}
